	public GuiElement getElementAtPoint(int x, int y)
	{
		if(!containsPoint(x, y))
		{
			return null;
		}

		GuiElement clicked = clickable? this : null;

		for(GuiElement child: children)
		{
			GuiElement element = child.getElementAtPoint(x - bounds.x(), y - bounds.y());

			if(element != null)
			{
				clicked = element;
			}
		}

		return clicked;
	}

